import json, sys
exec(open("/home/claude/pm_italien/freq2.py").read())
P = "/home/claude/pm_italien/data_italien.json"
d = json.load(open(P))
ordre = list(json.load(open(f"{S}/verbes_fr.json")).keys())
niches = []
for line in [l for l in V.strip().split("\n") if l.strip()]:
    p = line.split("|"); assert len(p) == 15, (len(p), line[:40])
    key, frl, itl, iw, pr, api, mc, sc, de, fo, efr, mfr, eit, mit, li = p
    lex = key.split("+")
    f = fr(lex, ["VER", "AUX"], exclure={"suis"} if key == "suivre" else ())
    i = it(iw, "V")
    assert f and i, (key, iw)
    for a, b in ((efr, mfr), (eit, mit)): assert b in a, (key, a, b)
    niches.append(dict(fr=frl, cible=itl, prononciation=pr, api=f"/{api}/", mot_cle=mc, scene=sc, decryptage=de,
        formes=fo, exemple_fr=efr, exemple_fr_mot=mfr, exemple_cible=eit, exemple_cible_mot=mit, lien=li,
        categorie="verbes", sous_categories=["verbes"], lex=lex, lemme_it=iw, audio_mot=None, audio_phrase=None,
        zipf={"fr": f, "it": i}, zipf_fr=f["parle"], zipf_cible=i["parle"], zipf_source="mesuré", _key=key))
assert [n["_key"] for n in niches] == ordre, [(a, b) for a, b in zip([n["_key"] for n in niches], ordre) if a != b][:5]
assert len({n["cible"] for n in niches}) == 100 and len({n["fr"] for n in niches}) == 100
for k, n in enumerate(niches):
    n["n"] = k; n.pop("_key")
    n["occ100M"] = {lg: {kk: int(round(10 ** (v - 1), -int(math.floor(v - 1)) + 2)) for kk, v in sc_.items() if v}
                    for lg, sc_ in n["zipf"].items()}
d["pieces"] = [p for p in d["pieces"] if p["id"] != "verbes"]
d["pieces"].insert(1, {"id": "verbes", "titre_fr": "Les verbes", "titre_cible": "I verbi", "decor": "atelier",
                       "ordre": "Zipf FR parlé (Lexique 3 films + OpenSubtitles 2018), décroissant", "niches": niches})
json.dump(d, open(P, "w"), ensure_ascii=False, indent=1)
print("ok", len(niches))
